import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import {createHalEngine} from './config.js';
import {validateMessage} from './transport/ws/validation.js';
import {HAL_WS_SUBPROTOCOL} from './transport/ws/subprotocol.js';
import {askOnOpen, deferred, startEngineWith, stopEngines} from './transport/wsTestSupport.js';
import {createChatOrchestrator} from './orchestration/chatOrchestrator.js';
import {PromptBuilder} from './infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './orchestration/tools/registry.js';
import {InMemorySessionStore} from './infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from './infrastructure/stores/mongo/mongoSessionStore.js';
import {fakeCollection} from './infrastructure/stores/mongo/mongoTestSupport.js';
import {fiveMemberStore} from './infrastructure/stores/sessionStoreTestSupport.js';
import {setLogger} from './shared/logger.js';
import {ErrorCodes} from './types/messages.js';
import type {AIProvider, MessageChunk} from './types/ai.js';
import type {SessionEntry} from './types/session.js';
import type {SessionListOptions, SessionStore} from './types/sessionStore.js';

// Acceptance tests for #144: delivering a user's conversation list over the WebSocket protocol.

interface WireSummary {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}

interface WireFrame {
  type: string;
  sessionId?: string;
  resumed?: boolean;
  entryCount?: number;
  code?: string;
  message?: string;
  index?: number;
  entry?: SessionEntry;
  conversations?: WireSummary[];
}

interface RecordedListCall {
  userId: string | number;
  options: SessionListOptions | undefined;
}

describe('conversation list over the WebSocket protocol', () => {
  const engines: Array<{stop: () => Promise<void>}> = [];
  const sockets: WebSocket[] = [];

  afterEach(async () => {
    for (const socket of sockets.splice(0)) socket.terminate();
    for (const engine of engines.splice(0)) await engine.stop();
    await stopEngines();
    setLogger();
  });

  it('validates list_conversations with optional integer limit 1-200 and composite before cursor, and refuses bad values by field name', () => {
    const bare = validateMessage({type: 'list_conversations'});
    const paged = validateMessage({
      type: 'list_conversations',
      limit: 10,
      before: {updatedAt: '2099-01-02T00:00:00.000Z', sessionId: 'conv-2'},
      userId: 'u2',
    });
    const badLimits = [0, 201, 1.5, '10'].map(limit => validateMessage({type: 'list_conversations', limit}));
    const badCursors = [
      'not a date',
      {updatedAt: 'not a date', sessionId: 'conv-1'},
      {updatedAt: '2099-01-01T00:00:00.000Z'},
      {sessionId: 'conv-1'},
    ].map(before => validateMessage({type: 'list_conversations', before}));

    expect({bare, paged, badLimits, badCursors}).toEqual({
      bare: {valid: true, data: {type: 'list_conversations'}},
      paged: {
        valid: true,
        data: {
          type: 'list_conversations',
          limit: 10,
          before: {updatedAt: '2099-01-02T00:00:00.000Z', sessionId: 'conv-2'},
        },
      },
      badLimits: badLimits.map(() => ({valid: false, error: expect.stringContaining('limit')})),
      badCursors: badCursors.map(() => ({valid: false, error: expect.stringContaining('before')})),
    });
  });

  it('delivers the connecting user own conversation list newest first with ISO timestamps, ignores frame userId, pages with limit and before, and resumes a listed id', async () => {
    const {store, recordedCalls} = seededTrackedStore();
    const transport = {port: 0, resume: {enabled: true}, history: {enabled: true}};
    const {wsBase} = await launchEngine({session: store, transport});
    const client = openSocket(wsBase);
    const connected = await nextFrameMatching(client, frame => frame.type === 'connected');
    const currentSessionId = connected.sessionId ?? '';

    client.send(JSON.stringify({type: 'list_conversations', userId: 'u2'}));
    client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    const firstTurn = await framesUntilType(client, 'pong');
    const firstList = firstTurn.find(frame => frame.type === 'conversation_list');

    const cursorRow = firstList?.conversations?.[1];
    const cursor = cursorRow ? {updatedAt: cursorRow.updatedAt, sessionId: cursorRow.sessionId} : undefined;
    client.send(JSON.stringify({type: 'list_conversations', limit: 2, before: cursor}));
    client.send(JSON.stringify({type: 'ping', timestamp: 2}));
    const secondTurn = await framesUntilType(client, 'pong');
    const secondList = secondTurn.find(frame => frame.type === 'conversation_list');

    const resumeClient = openSocket(`${wsBase}?sessionId=conv-1`);
    const resumeConnected = await nextFrameMatching(resumeClient, frame => frame.type === 'connected');
    resumeClient.send(JSON.stringify({type: 'ping', timestamp: 3}));
    const resumeFollowup = await framesUntilType(resumeClient, 'pong');

    const firstRows = firstList?.conversations ?? [];
    const firstSummaryKeys = firstRows[0] ? Object.keys(firstRows[0]).sort() : [];
    const timestampsIso =
      firstRows.length > 0 && firstRows.every(row => isIsoDate(row.createdAt) && isIsoDate(row.updatedAt));

    expect({
      firstTypes: firstTurn.map(frame => frame.type),
      firstIds: firstRows.map(row => row.sessionId),
      firstSummaryKeys,
      timestampsIso,
      recordedCalls,
      secondIds: (secondList?.conversations ?? []).map(row => row.sessionId),
      resumeConnected,
      resumeUpserts: resumeFollowup.filter(frame => frame.type === 'entry_upsert'),
    }).toEqual({
      firstTypes: ['conversation_list', 'pong'],
      firstIds: ['conv-3', 'conv-2', 'conv-1', currentSessionId],
      firstSummaryKeys: ['createdAt', 'entryCount', 'sessionId', 'updatedAt'],
      timestampsIso: true,
      recordedCalls: [
        {userId: 'u1', options: {limit: undefined, before: undefined}},
        {userId: 'u1', options: {limit: 2, before: {updatedAt: '2099-01-02T00:00:00.000Z', sessionId: 'conv-2'}}},
      ],
      secondIds: ['conv-1', currentSessionId],
      resumeConnected: {
        type: 'connected',
        sessionId: 'conv-1',
        message: expect.any(String),
        examplePrompts: [],
        resumed: true,
        entryCount: 1,
      },
      resumeUpserts: [
        {type: 'entry_upsert', index: 0, entry: {role: 'user', content: 'topic 1', timestamp: '2099-01-01T00:00:00.000Z'}},
      ],
    });
  });

  it('answers list_conversations before a streaming user_message finishes on the same session', async () => {
    const gate = deferred();
    const provider: AIProvider = {
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        yield {type: 'text', text: 'partial'};
        await gate.until;
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), new ToolRegistry());
    const serverOptions = {sessionStore: new InMemorySessionStore(), orchestrator, history: {enabled: true}};
    const {url} = await startEngineWith(serverOptions);
    const {client, finished} = askOnOpen(url, {until: 'stream_end'});
    const observedTypes: string[] = [];
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      observedTypes.push(frame.type);
    });

    await onceFrame(client, frame => frame.type === 'entry_delta');
    client.send(JSON.stringify({type: 'list_conversations'}));
    await onceFrame(client, frame => frame.type === 'conversation_list' || frame.type === 'error');
    gate.release();
    await finished;

    const listIndex = observedTypes.indexOf('conversation_list');
    const streamEndIndex = observedTypes.indexOf('stream_end');
    expect({
      seenList: listIndex >= 0,
      beforeStreamEnd: listIndex >= 0 && listIndex < streamEndIndex,
      observedTypes,
    }).toEqual({
      seenList: true,
      beforeStreamEnd: true,
      observedTypes: expect.arrayContaining(['conversation_list', 'stream_end']),
    });
  });

  it('answers UNSUPPORTED when history is off, when the store omits listFor, or when StoreCannotList is thrown, and SERVER_ERROR without store details when listFor rejects', async () => {
    const capturedErrors: Array<Record<string, unknown>> = [];
    const quiet = () => undefined;
    setLogger({
      debug: quiet,
      info: quiet,
      warn: quiet,
      error: (category, message, fields) => void capturedErrors.push({category, message, ...fields}),
    });

    const historyOff = await askListOverEngine(new InMemorySessionStore(), {port: 0});
    const omittingListFor = await askListOverEngine(fiveMemberStore, {port: 0, history: {enabled: true}});
    const mongoWithoutFind = new MongoSessionStore({collection: fakeCollection()});
    const cannotList = await askListOverEngine(mongoWithoutFind, {port: 0, history: {enabled: true}});

    const failingCollection = fakeCollection({
      find: () => ({toArray: () => Promise.reject(new Error('secret-mongo-host-down'))}),
    });
    const mongoFailing = new MongoSessionStore({collection: failingCollection});
    const rejected = await askListOverEngine(mongoFailing, {port: 0, history: {enabled: true}});

    const errorMessage = rejected.reply?.message ?? '';
    expect({
      errorCodeDefined: ErrorCodes,
      connectedKeysWhenOff: Object.keys(historyOff.connected).sort(),
      historyOffReply: {type: historyOff.reply?.type, code: historyOff.reply?.code},
      omittingListForReply: {type: omittingListFor.reply?.type, code: omittingListFor.reply?.code},
      cannotListReply: {type: cannotList.reply?.type, code: cannotList.reply?.code},
      rejectedReply: {type: rejected.reply?.type, code: rejected.reply?.code},
      leakedStoreDetail: errorMessage.includes('secret-mongo-host-down'),
      stayedOpenForPong: rejected.pongSeen,
      loggedSessionId: capturedErrors.some(entry => entry.sessionId === rejected.connected.sessionId),
    }).toEqual({
      errorCodeDefined: expect.objectContaining({UNSUPPORTED: 'UNSUPPORTED'}),
      connectedKeysWhenOff: ['examplePrompts', 'message', 'sessionId', 'type'],
      historyOffReply: {type: 'error', code: 'UNSUPPORTED'},
      omittingListForReply: {type: 'error', code: 'UNSUPPORTED'},
      cannotListReply: {type: 'error', code: 'UNSUPPORTED'},
      rejectedReply: {type: 'error', code: 'SERVER_ERROR'},
      leakedStoreDetail: false,
      stayedOpenForPong: true,
      loggedSessionId: true,
    });
  });

  it('warns at startup when history is enabled without resume', async () => {
    const warnings: Array<{category: string; message: string}> = [];
    const quiet = () => undefined;
    setLogger({
      debug: quiet,
      info: quiet,
      warn: (category, message) => void warnings.push({category, message}),
      error: quiet,
    });

    const transport = {port: 0, history: {enabled: true}};
    const engine = createHalEngine({
      provider: {type: 'mock'},
      prompt: {identity: 'test'},
      auth: {ws: async () => ({id: 'u1'})},
      transport,
    });
    engines.push(engine);
    await engine.start();

    expect(warnings.some(entry => /history/i.test(entry.message) && /resume/i.test(entry.message))).toBe(true);
  });

  function openSocket(url: string): WebSocket {
    const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
    sockets.push(client);
    return client;
  }

  async function launchEngine(options: {session: SessionStore; transport: Record<string, unknown>}) {
    const engine = createHalEngine({
      provider: {type: 'mock'},
      prompt: {identity: 'test'},
      auth: {ws: async () => ({id: 'u1'})},
      session: options.session,
      transport: options.transport,
    });
    engines.push(engine);
    await engine.start();
    const {port} = engine.server.address() as AddressInfo;
    return {engine, wsBase: `ws://127.0.0.1:${port}/hal/ws`};
  }

  async function askListOverEngine(session: SessionStore, transport: Record<string, unknown>) {
    const {wsBase} = await launchEngine({session, transport});
    const client = openSocket(wsBase);
    const connected = await nextFrameMatching(client, frame => frame.type === 'connected');
    client.send(JSON.stringify({type: 'list_conversations'}));
    client.send(JSON.stringify({type: 'ping', timestamp: 9}));
    const frames = await framesUntilType(client, 'pong');
    const reply = frames.find(frame => frame.type === 'conversation_list' || frame.type === 'error');
    const pongSeen = frames.some(frame => frame.type === 'pong');
    return {connected, reply, pongSeen};
  }
});

function seededTrackedStore(): {store: SessionStore; recordedCalls: RecordedListCall[]} {
  const inner = new InMemorySessionStore();
  seedConversation(inner, 'conv-1', 'u1', 'topic 1', '2099-01-01T00:00:00.000Z');
  seedConversation(inner, 'conv-2', 'u1', 'topic 2', '2099-01-02T00:00:00.000Z');
  seedConversation(inner, 'conv-3', 'u1', 'topic 3', '2099-01-03T00:00:00.000Z');
  seedConversation(inner, 'conv-other', 'u2', 'other secret', '2099-01-04T00:00:00.000Z');

  const recordedCalls: RecordedListCall[] = [];
  const store: SessionStore = {
    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    get: sessionId => inner.get(sessionId),
    delete: sessionId => inner.delete(sessionId),
    count: () => inner.count(),
    clear: () => inner.clear(),
    lookup: sessionId => inner.lookup(sessionId),
    latestFor: userId => inner.latestFor(userId),
    listFor: (userId, options) => {
      recordedCalls.push({userId, options});
      return inner.listFor(userId, options);
    },
  };
  return {store, recordedCalls};
}

function seedConversation(
  store: InMemorySessionStore,
  sessionId: string,
  userId: string,
  content: string,
  timestamp: string
): void {
  const session = store.create(sessionId, userId);
  session.entries.push({role: 'user', content, timestamp});
}

function isIsoDate(text: string): boolean {
  const parsed = new Date(text);
  return Number.isFinite(parsed.getTime()) && parsed.toISOString() === text;
}

function nextFrameMatching(client: WebSocket, predicate: (frame: WireFrame) => boolean): Promise<WireFrame> {
  return new Promise<WireFrame>(resolve => {
    const onMessage = (raw: unknown) => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      if (!predicate(frame)) return;
      client.off('message', onMessage);
      resolve(frame);
    };
    client.on('message', onMessage);
  });
}

function onceFrame(client: WebSocket, predicate: (frame: WireFrame) => boolean): Promise<WireFrame> {
  return nextFrameMatching(client, predicate);
}

function framesUntilType(client: WebSocket, targetType: string): Promise<WireFrame[]> {
  const collected: WireFrame[] = [];
  return new Promise<WireFrame[]>(resolve => {
    const onMessage = (raw: unknown) => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      collected.push(frame);
      if (frame.type !== targetType) return;
      client.off('message', onMessage);
      resolve(collected);
    };
    client.on('message', onMessage);
  });
}

