    const cursorRow = firstList?.conversations?.[1];
    const cursor = cursorRow ? {updatedAt: cursorRow.updatedAt, sessionId: cursorRow.sessionId} : undefined;
    client.send(JSON.stringify({type: 'list_conversations', limit: 2, before: cursor}));
    client.send(JSON.stringify({type: 'ping', timestamp: 2}));
    const secondTurn = await framesUntilType(client, 'pong');
    const secondList = secondTurn.find(frame => frame.type === 'conversation_list');

    const resumeClient = openSocket(`${wsBase}?sessionId=conv-1`);
    const resumeConnected = await nextFrameMatching(resumeClient, frame => frame.type === 'connected');
    resumeClient.send(JSON.stringify({type: 'ping', timestamp: 3}));
    const resumeFollowup = await framesUntilType(resumeClient, 'pong');

    const firstRows = firstList?.conversations ?? [];
    const firstSummaryKeys = firstRows[0] ? Object.keys(firstRows[0]).sort() : [];
    const timestampsIso =
      firstRows.length > 0 && firstRows.every(row => isIsoDate(row.createdAt) && isIsoDate(row.updatedAt));

    expect({
      firstTypes: firstTurn.map(frame => frame.type),
      firstIds: firstRows.map(row => row.sessionId),
      firstSummaryKeys,
      timestampsIso,
      recordedCalls,
      secondIds: (secondList?.conversations ?? []).map(row => row.sessionId),
      resumeConnected,
      resumeUpserts: resumeFollowup.filter(frame => frame.type === 'entry_upsert'),
    }).toEqual({
      firstTypes: ['conversation_list', 'pong'],
      firstIds: ['conv-3', 'conv-2', 'conv-1', currentSessionId],
      firstSummaryKeys: ['createdAt', 'entryCount', 'sessionId', 'updatedAt'],
      timestampsIso: true,
      recordedCalls: [
        {userId: 'u1', options: {limit: undefined, before: undefined}},
        {userId: 'u1', options: {limit: 2, before: {updatedAt: '2099-01-02T00:00:00.000Z', sessionId: 'conv-2'}}},
      ],
      secondIds: ['conv-1', currentSessionId],
      resumeConnected: {
        type: 'connected',
        sessionId: 'conv-1',
        message: expect.any(String),
        examplePrompts: [],
        resumed: true,
        entryCount: 1,
      },
      resumeUpserts: [
        {type: 'entry_upsert', index: 0, entry: {role: 'user', content: 'topic 1', timestamp: '2099-01-01T00:00:00.000Z'}},
      ],
    });
  });

  it('answers list_conversations before a streaming user_message finishes on the same session', async () => {
    const gate = deferred();
    const provider: AIProvider = {
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        yield {type: 'text', text: 'partial'};
        await gate.until;
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), new ToolRegistry());
    const serverOptions = {
      app: (() => undefined) as unknown as Express,
      wsAuth: async () => ({id: 'u1'}),
      sessionStore: new InMemorySessionStore(),
      orchestrator,
      history: {enabled: true},
    };
    const hal = createServer(serverOptions);
    servers.push(hal);
