    const client = openSocket(`ws://127.0.0.1:${port}/hal/ws`);
    const observedTypes: string[] = [];
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      observedTypes.push(frame.type);
    });

    await nextFrameMatching(client, frame => frame.type === 'connected');
    client.send(JSON.stringify({type: 'user_message', content: 'hold stream'}));
    await nextFrameMatching(client, frame => frame.type === 'entry_delta');
    client.send(JSON.stringify({type: 'list_conversations'}));
    await nextFrameMatching(client, frame => frame.type === 'conversation_list' || frame.type === 'error');
